// SR-3: a datagram that is valid DNS and valid CoAP is reported unknown, never arbitrarily identified; a hint selects
// the one candidate; a competing candidate that exhausts its budget blocks the other identification.
func TestSecurityAmbiguousDatagramIsUnknownAndACompetingBudgetBlocks(t *testing.T) {
	data, _ := hex.DecodeString("480181800001000100000000136b377a7835623463747a6b6b366f616d38396f03636f6d0000010001000001000100000000000400000000")
	d, err := NewDatagram(contracts.DefaultConfig())
	if err != nil {
		t.Fatal(err)
	}
	got, err := d.Inspect(data, "")
	if err != nil {
		t.Fatal(err)
	}
	if got.Status != contracts.Unknown || !strings.Contains(got.Reason, "Ambiguous") || got.ApplicationProtocol != nil {
		t.Fatalf("DNS/CoAP ambiguity: %+v", got)
	}
	if d.Metrics.ParserCalls != 2 {
		t.Fatalf("parser calls %d, want 2 (both candidates validated)", d.Metrics.ParserCalls)
	}
	hinted, _ := d.Inspect(data, "dns")
	if hinted.Status != contracts.Identified || hinted.ApplicationProtocol == nil || *hinted.ApplicationProtocol != "dns" {
		t.Fatalf("dns hint: %+v", hinted)
	}
	over := append([]byte{}, data...)
	over[6], over[7] = 0x00, 0x80 // 128 answers: DNS exceeds its record budget while CoAP still validates
	blocked, _ := d.Inspect(over, "")
	if blocked.Status != contracts.BudgetExhausted || blocked.ApplicationProtocol != nil {
		t.Fatalf("competing budget failure: %+v", blocked)
	}
}

// kexinitPacket is test_fingerprints.kexinit: one SSH binary packet carrying a KEXINIT (msg 20 by default).
func kexinitPacket(lists [][]byte, firstFollows byte, reserved []byte, msg byte, padding int) []byte {
	if lists == nil {
		lists = [][]byte{[]byte("curve25519-sha256,ecdh-sha2-nistp256"), []byte("ssh-ed25519,rsa-sha2-512"),
			[]byte("aes128-ctr,aes256-gcm@openssh.com"), []byte("aes128-ctr"), []byte("hmac-sha2-256,umac-128-etm@openssh.com"),
			[]byte("hmac-sha2-256"), []byte("none,zlib@openssh.com"), []byte("none"), nil, nil}
	}
	if reserved == nil {
		reserved = make([]byte, 4)
	}
	payload := []byte{msg}
	for i := 0; i < 16; i++ {
		payload = append(payload, byte(i))
	}
	for _, l := range lists {
		payload = append(payload, byte(len(l)>>24), byte(len(l)>>16), byte(len(l)>>8), byte(len(l)))
		payload = append(payload, l...)
	}
	payload = append(append(payload, firstFollows), reserved...)
	if padding < 0 {
		padding = 8 - (len(payload)+5)%8
		if padding < 4 {
			padding += 8
		}
	}
	n := len(payload) + 1 + padding
	out := []byte{byte(n >> 24), byte(n >> 16), byte(n >> 8), byte(n), byte(padding)}
	return append(append(out, payload...), make([]byte, padding)...)
}

func derivedEvidence(o contracts.Observation) map[string]string {
	out := map[string]string{}
	for _, e := range o.Evidence {
		if e.Strength == "derived" {
			out[e.Field] = e.Value
		}
	}
	return out
}

// SR-21: a post-identification continuation only adds derived evidence; a malformed, truncated or over-budget
// continuation and EOF never turn the published SSH identification into another status.
func TestSecuritySSHContinuationNeverChangesThePublishedIdentification(t *testing.T) {
	banner := []byte("SSH-2.0-x\r\n")
	fp := contracts.DefaultConfig()
	fp.Fingerprints = true
	start := func(cfg contracts.Config) *Inspector {
		t.Helper()
		in, err := New(cfg, "")
		if err != nil {
			t.Fatal(err)
		}
		ev := in.Feed(banner)
		if len(ev) != 1 || ev[0].Kind != contracts.Updated || ev[0].Observation.Status != contracts.Identified ||
			ev[0].Observation.ApplicationProtocol == nil || *ev[0].Observation.ApplicationProtocol != "ssh" {
			t.Fatalf("banner: %+v", ev)
		}
		return in
	}
	identifiedOnly := func(name string, in *Inspector, events []contracts.Event) {
		t.Helper()
		for _, e := range events {
			if e.Observation.Status != contracts.Identified || len(derivedEvidence(e.Observation)) != 0 {
				t.Fatalf("%s: event %s %+v", name, e.Kind, e.Observation)
			}
		}
		if in.Observation.Status != contracts.Identified || len(derivedEvidence(in.Observation)) != 0 ||
			in.Observation.ApplicationProtocol == nil || *in.Observation.ApplicationProtocol != "ssh" {
			t.Fatalf("%s: observation %+v", name, in.Observation)
		}
	}
	// The valid continuation refines with HASSH.
	good := start(fp)
	ev := good.Feed(kexinitPacket(nil, 0, nil, 20, -1))
	if len(ev) != 1 || ev[0].Kind != contracts.Refined || ev[0].Observation.Status != contracts.Identified || derivedEvidence(ev[0].Observation)["hassh"] == "" {
		t.Fatalf("valid KEXINIT: %+v", ev)
	}
	ended := start(fp)
	identifiedOnly("eof", ended, ended.End("fin"))
	for name, packet := range map[string][]byte{
		"msg 21":          kexinitPacket(nil, 0, nil, 21, -1),
		"padding 2":       kexinitPacket(nil, 0, nil, 20, 2),
		"first follows 2": kexinitPacket(nil, 2, nil, 20, -1),
		"reserved":        kexinitPacket(nil, 0, []byte{0, 0, 0, 1}, 20, -1),
		"name grammar":    kexinitPacket([][]byte{[]byte("a\x00"), nil, nil, nil, nil, nil, nil, nil, nil, nil}, 0, nil, 20, -1),
		"huge length":     {0, 0, 0x9c, 0x40},
	} {
		in := start(fp)
		events := in.Feed(packet)
		events = append(events, in.End("fin")...)
		identifiedOnly(name, in, events)
	}
	small := fp
	small.MaxBytes = 64
	budget := start(small)
	events := budget.Feed(make([]byte, 60))
	identifiedOnly("byte budget", budget, append(events, budget.End("fin")...))
}

