func evidenceOf(o contracts.Observation, field string) (contracts.Evidence, bool) {
	for _, e := range o.Evidence {
		if e.Field == field {
			return e, true
		}
	}
	return contracts.Evidence{}, false
}

// SR-41: an outer encrypted_client_hello is validated structurally and reported only as the extension type, as a
// client offer; the public name stays the asserted hostname; a malformed extension makes the ClientHello malformed
// with no hostname; the QUIC Initial path reports the same class.
func TestSecurityEncryptedClientHelloIsValidatedAndReportedAsAnOffer(t *testing.T) {
	fp := contracts.DefaultConfig()
	fp.Fingerprints = true
	hello := secHex(t, echHello)
	o, _ := streamObservation(t, fp, hello)
	if o.Status != contracts.Identified || o.Encryption == nil || *o.Encryption != "tls" || o.Hostname == nil || *o.Hostname != "public.example.net" {
		t.Fatalf("outer ECH hello: %+v", o)
	}
	ech, ok := evidenceOf(o, "tls_ech")
	if !ok || ech.Value != "outer" || ech.Source != "wire:client_hello" || ech.Strength != "offered" {
		t.Fatalf("tls_ech evidence %+v", ech)
	}
	if inner, _ := streamObservation(t, contracts.DefaultConfig(), secHex(t, echInnerHello)); inner.Status != contracts.Identified {
		t.Fatalf("inner: %+v", inner)
	} else if e, _ := evidenceOf(inner, "tls_ech"); e.Value != "inner" {
		t.Fatalf("inner tls_ech %+v", e)
	}
	if plain, _ := streamObservation(t, fp, secHex(t, echNoSNIHello)); plain.Hostname != nil {
		t.Fatalf("no SNI: %+v", plain)
	}
	for _, s := range echVariantHellos {
		v, _ := streamObservation(t, contracts.DefaultConfig(), secHex(t, s))
		if e, _ := evidenceOf(v, "tls_ech"); e.Value != "outer" {
			t.Fatalf("suite variant %s: %+v", s, v)
		}
	}
	for _, s := range echMalformedHellos {
		m, _ := streamObservation(t, contracts.DefaultConfig(), secHex(t, s))
		if m.Status != contracts.Malformed || m.Hostname != nil {
			t.Fatalf("malformed ECH %s: %+v", s, m)
		}
	}
	for split := 1; split < len(hello); split += 5 {
		in, _ := New(contracts.DefaultConfig(), "")
		in.Feed(hello[:split])
		in.Feed(hello[split:])
		if e, _ := evidenceOf(in.Observation, "tls_ech"); e.Value != "outer" {
			t.Fatalf("split %d: %+v", split, in.Observation)
		}
	}
	dcid := []byte{0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08}
	frames := testframes.CryptoFrames(hello[5:])
	datagram := testframes.QUICInitial(1, dcid, nil, frames[0], 2, nil, 1200)
	q := datagramObservation(t, contracts.DefaultConfig(), datagram, "")
	if q.Status != contracts.Identified || q.Encryption == nil || *q.Encryption != "quic" || q.Hostname == nil || *q.Hostname != "public.example.net" {
		t.Fatalf("QUIC Initial with ECH: %+v", q)
	}
	if e, _ := evidenceOf(q, "tls_ech"); e.Value != "outer" || e.Source != "quic_client_hello" {
		t.Fatalf("QUIC tls_ech %+v", e)
	}
}

// SR-13: plaintext refinement requires a previously identified TLS envelope: an HTTP or SSH identification, an
// invalidated TLS envelope and an inspector before identification all refuse decrypted bytes; an accepted
// refinement keeps the TLS envelope and the decrypted provenance.
func TestSecurityPlaintextRefinementRequiresAnIdentifiedTLSEnvelope(t *testing.T) {
	refused := func(name string, in *Inspector) {
		t.Helper()
		before := in.Observation
		if events, err := in.FeedDecrypted([]byte("GET / HTTP/1.1\r\nHost: inner.example\r\n\r\n")); err == nil || len(events) != 0 ||
			!strings.Contains(err.Error(), "Decrypted data requires a previously identified TLS envelope") {
			t.Fatalf("%s: decrypted bytes accepted: %v %v", name, events, err)
		}
		if !before.Equal(in.Observation) {
			t.Fatalf("%s: a refused refinement changed the observation", name)
		}
	}
	refused("before identification", mustNew(t))
	http := mustNew(t)
	http.Feed([]byte("GET / HTTP/1.1\r\nHost: a.example\r\n\r\n"))
	refused("HTTP", http)
	ssh := mustNew(t)
	ssh.Feed([]byte("SSH-2.0-x\r\n"))
	refused("SSH", ssh)
	hello := secHex(t, echHello)
	invalidated := mustNew(t)
	invalidated.Feed(hello)
	if invalidated.Observation.Encryption == nil || *invalidated.Observation.Encryption != "tls" {
		t.Fatalf("TLS envelope: %+v", invalidated.Observation)
	}
	invalidated.Invalidate("conflict")
	refused("invalidated TLS", invalidated)
	tls := mustNew(t)
	tls.Feed(hello)
	events, err := tls.FeedDecrypted([]byte("GET / HTTP/1.1\r\nHost: inner.example\r\n\r\n"))
	if err != nil || len(events) == 0 {
		t.Fatalf("TLS envelope refused plaintext: %v %v", events, err)
	}
	o := tls.Observation
	if o.Encryption == nil || *o.Encryption != "tls" || o.ApplicationProtocol == nil || *o.ApplicationProtocol != "http/1.1" {
		t.Fatalf("refinement lost the envelope: %+v", o)
	}
	decrypted := false
	for _, e := range o.Evidence {
		if e.Field == "hostname" && e.Value == "inner.example" {
			decrypted = strings.HasPrefix(e.Source, "decrypted")
		}
	}
	if !decrypted || o.Hostname == nil || *o.Hostname != "inner.example" {
		t.Fatalf("inner hostname provenance: %+v", o)
	}
}

// SR-19: parser contexts are retained only with RetainContexts, and the retained values (path, query, user agent,
// headers) never reach the observation or the events.
func TestSecurityParserContextsAreRetainedOnlyWhenConfiguredAndNeverEmitted(t *testing.T) {
	head := []byte("GET /path/x?secret=1 HTTP/1.1\r\nHost: Example.COM\r\nUser-Agent: Agent/1.0\r\n")
	for _, retain := range []bool{false, true} {
		cfg := contracts.DefaultConfig()
		cfg.RetainContexts = retain
		in, err := New(cfg, "")
		if err != nil {
			t.Fatal(err)
		}
		events := in.Feed(head)
		if in.parser == nil {
			t.Fatalf("retain=%v: no parser while the header block is open", retain)
		}
		contexts := in.parser.Result().Contexts
		if !retain && contexts != nil {
			t.Fatalf("contexts retained without the option: %v", contexts)
		}
		if retain {
			for name, want := range map[string]string{"http-req-method": "GET", "http-req-uri-path": "/path/x", "http-req-version": "HTTP/1.1",
				"http-req-user-agent-header": "Agent/1.0"} {
				if got, _ := contexts[name].([]byte); string(got) != want {
					t.Fatalf("context %s = %q, want %q", name, got, want)
				}
			}
		}
		events = append(events, in.Feed([]byte("\r\n"))...)
		events = append(events, in.End("fin")...)
		if in.Observation.Hostname == nil || *in.Observation.Hostname != "example.com" {
			t.Fatalf("retain=%v: %+v", retain, in.Observation)
		}
		text := fmt.Sprintf("%+v %+v", in.Observation, events)
		for _, leak := range []string{"secret", "/path/x", "Agent/1.0"} {
			if strings.Contains(text, leak) {
				t.Fatalf("retain=%v: %q reached the output: %s", retain, leak, text)
			}
		}
	}
}

func fieldValue(o contracts.Observation, field string) string {
	e, _ := evidenceOf(o, field)
	return e.Value
}

// SR-27: an application shift never removes the carrier: a failed, missing, truncated or over-budget shifted phase
// keeps the carrier identified with the shifted_payload context, and both phases share one byte budget.
func TestSecurityShiftKeepsTheCarrierAndSharesOneBudget(t *testing.T) {
	connect := []byte("CONNECT example.com:443 HTTP/1.1\r\nHost: example.com:443\r\nProxy-Connection: keep-alive\r\n\r\n")
	hello := secHex(t, echHello)
	run := func(cfg contracts.Config, data []byte) *Inspector {
		t.Helper()
		in, err := New(cfg, "")
		if err != nil {
			t.Fatal(err)
		}
		in.Feed(data)
		return in
	}
	carrier := func(name string, o contracts.Observation, protocol, payload string) {
		t.Helper()
		if o.Status != contracts.Identified || o.ApplicationProtocol == nil || *o.ApplicationProtocol != protocol ||
			fieldValue(o, "shifted_payload") != payload {
			t.Fatalf("%s: %+v", name, o)
		}
	}
	garbage := run(contracts.DefaultConfig(), append(append([]byte{}, connect...), bytes.Repeat([]byte{0xff}, 40)...))
	carrier("garbage after CONNECT", garbage.Observation, "http/1.1", "unknown")
	if fieldValue(garbage.Observation, "shift") != "http-connect" {
		t.Fatalf("shift marker: %+v", garbage.Observation)
	}
	pending := run(contracts.DefaultConfig(), connect)
	ended := pending.End("EOF")
	if len(ended) != 1 || ended[0].Kind != contracts.Shifted {
		t.Fatalf("EOF in the shifted phase: %+v", ended)
	}
	carrier("EOF after CONNECT", pending.Observation, "http/1.1", "incomplete")
	smtp := run(contracts.DefaultConfig(), []byte("EHLO client.example\r\nSTARTTLS\r\n\x16\x03\x01\x00\x05abcde"))
	carrier("malformed TLS after STARTTLS", smtp.Observation, "smtp", "malformed")
	pg := run(contracts.DefaultConfig(), append([]byte{0, 0, 0, 8, 4, 0xd2, 0x16, 0x2f}, "GET / HTTP/1.1\r\nHost: a\r\n\r\n"...))
	if o := pg.Observation; o.ApplicationProtocol == nil || *o.ApplicationProtocol != "postgresql" ||
		(fieldValue(o, "shifted_payload") != "unknown" && fieldValue(o, "shifted_payload") != "malformed") {
		t.Fatalf("HTTP after the PostgreSQL SSL request: %+v", o)
	}
	for _, extra := range []int{40, 200} {
		cfg := contracts.DefaultConfig()
		cfg.MaxBytes = len(connect) + extra
		in := run(cfg, append(append([]byte{}, connect...), hello...))
		carrier("shared budget", in.Observation, "http/1.1", "budget_exhausted")
		if in.Metrics.BytesInspected > cfg.MaxBytes {
			t.Fatalf("budget %d: %d bytes inspected across both phases", cfg.MaxBytes, in.Metrics.BytesInspected)
		}
	}
	whole := run(contracts.DefaultConfig(), append(append([]byte{}, connect...), hello...))
	if o := whole.Observation; o.Encryption == nil || *o.Encryption != "tls" || fieldValue(o, "shift_from") != "http/1.1" {
		t.Fatalf("complete shifted phase: %+v", o)
	}
}

func h2Fields(in *Inspector) map[string]string {
	out := map[string]string{}
	for _, e := range in.Observation.Evidence {
		out[e.Field] = e.Value
	}
	return out
}

// SR-48: the HTTP/2 header block is decoded only within eight frames before HEADERS and eight frames per block; a
// block past either bound, or any HPACK error, keeps the SETTINGS identification with no header evidence; only
// closed labels and the :authority host are emitted, never the path, user agent or cookie.
func TestSecurityHTTP2HeaderBlockBoundsAndNoValueLeakage(t *testing.T) {
	settings := h2frame(4, 0, 0, nil)
	ping := h2frame(6, 0, 0, make([]byte, 8))
	open := append(append([]byte{}, h2Preface...), settings...)
	decoded := func(name string, stream []byte, want bool) map[string]string {
		t.Helper()
		in, fields := h2run(t, "", stream)
		if in.Observation.Status != contracts.Identified || in.Observation.ApplicationProtocol == nil || *in.Observation.ApplicationProtocol != "http/2" {
			t.Fatalf("%s: the identification changed: %+v", name, in.Observation)
		}
		if (fields["http2_method"] == "GET") != want || (in.Observation.Hostname != nil) != want {
			t.Fatalf("%s: header evidence %v (want decoded=%v)", name, fields, want)
		}
		return fields
	}
	pings := func(n int) []byte {
		out := append([]byte{}, open...)
		for i := 0; i < n; i++ {
			out = append(out, ping...)
		}
		return out
	}
	decoded("four PINGs", append(pings(4), h2frame(1, 0x5, 1, h2RequestBlock)...), true)
	decoded("twelve PINGs", append(pings(12), h2frame(1, 0x5, 1, h2RequestBlock)...), false)
	split := func(pieces int) []byte {
		out := append([]byte{}, open...)
		size := (len(h2RequestBlock) + pieces - 1) / pieces
		for i, start := 0, 0; start < len(h2RequestBlock); i, start = i+1, start+size {
			end := start + size
			if end > len(h2RequestBlock) {
				end = len(h2RequestBlock)
			}
			kind, flags := byte(9), byte(0)
			if i == 0 {
				kind, flags = 1, 0x1
			}
			if end == len(h2RequestBlock) {
				flags |= 0x4
			}
			out = append(out, h2frame(kind, flags, 1, h2RequestBlock[start:end])...)
		}
		return out
	}
	decoded("block in three frames", split(3), true)
	decoded("block in seventeen frames", split(17), false)
	decoded("HPACK index zero", append(append([]byte{}, open...), h2frame(1, 0x5, 1, []byte{0x80})...), false)
	block := []byte{0x82, 0x86}
	block = append(append(block, 0x44, 12), "/secret-path"...)
	block = append(append(block, 0x41, 15), "www.example.com"...)
	block = append(append(block, 0x7a, 13), "SecretAgent/9"...)
	block = append(append(block, 0x60, 14), "id=cookie-0001"...)
	in, _ := h2run(t, "", append(append([]byte{}, open...), h2frame(1, 0x5, 1, block)...))
	if fields := h2Fields(in); fields["http2_method"] != "GET" || in.Observation.Hostname == nil || *in.Observation.Hostname != "www.example.com" {
		t.Fatalf("literal request block: %+v", in.Observation)
	}
	text := fmt.Sprintf("%+v", in.Observation)
	for _, leak := range []string{"secret-path", "SecretAgent", "cookie-0001"} {
		if strings.Contains(text, leak) {
			t.Fatalf("%q emitted: %s", leak, text)
		}
	}
}

// SR-56: KEXINIT name-lists follow the RFC 4251 grammar (non-empty names of at most 64 characters): a list with an
// empty or 65-character name keeps the banner identification with no posture class, a 64-character name is
// accepted; the classes are closed labels and no algorithm name, list or cookie byte is emitted.
func TestSecuritySSHKexinitNameGrammarAndClosedClasses(t *testing.T) {
	banner := []byte("SSH-2.0-x\r\n")
	lists := func(first string) [][]byte {
		return [][]byte{[]byte(first), []byte("ssh-ed25519"), []byte("aes128-ctr"), []byte("aes128-ctr"), []byte("hmac-sha2-256"),
			[]byte("hmac-sha2-256"), []byte("none"), []byte("none"), nil, nil}
	}
	posture := func(first string) (contracts.Observation, bool) {
		t.Helper()
		in, err := New(contracts.DefaultConfig(), "")
		if err != nil {
			t.Fatal(err)
		}
		in.Feed(append(append([]byte{}, banner...), kexinitPacket(lists(first), 0, nil, 20, -1)...))
		in.End("fin")
		o := in.Observation
		if o.Status != contracts.Identified || o.ApplicationProtocol == nil || *o.ApplicationProtocol != "ssh" {
			t.Fatalf("%q: the banner identification changed: %+v", first, o)
		}
		_, classes := evidenceOf(o, "ssh_kex_class")
		return o, classes
	}
	long64 := "curve25519-sha256," + strings.Repeat("x", 64)
	o, ok := posture(long64)
	if !ok {
		t.Fatalf("a 64-character name refused: %+v", o)
	}
	for _, e := range o.Evidence {
		if strings.Contains(e.Value, "curve25519") || strings.Contains(e.Value, "xxxx") || strings.Contains(e.Value, "aes128") {
			t.Fatalf("an algorithm name was emitted: %+v", e)
		}
	}
	for _, bad := range []string{"curve25519-sha256," + strings.Repeat("x", 65), "curve25519-sha256,,ecdh-sha2-nistp256", ",curve25519-sha256"} {
		if o, ok := posture(bad); ok {
			t.Fatalf("%q: posture classes from a list outside the grammar: %+v", bad, o)
		}
	}
}

// recordedCase is one input a security-requirement Python test fed the reference, with the observation the
// reference produced (recorded before the Python reference was removed).
type recordedCase struct {
	Kind   string          `json:"kind"`
	Config json.RawMessage `json:"config"`
	Hint   string          `json:"hint"`
	Data   string          `json:"data"`
	Ended  bool            `json:"ended"`
	Obs    struct {
		Status              string     `json:"status"`
		Transport           string     `json:"transport"`
		Encryption          *string    `json:"encryption"`
		ApplicationProtocol *string    `json:"application_protocol"`
		Application         *string    `json:"application"`
		Hostname            *string    `json:"hostname"`
		Scope               string     `json:"scope"`
		Evidence            [][]string `json:"evidence"`
	} `json:"obs"`
}

func optional(p *string) string {
	if p == nil {
		return "<nil>"
	}
	return *p
}

// checkRecorded runs every recorded case through the Go engine and requires the reference's status, protocol,
// encryption, application, hostname, scope and evidence rows, and that no leak string appears in any observation.
func checkRecorded(t *testing.T, label, cases string, leaks ...string) int {
	t.Helper()
	var list []recordedCase
	if err := json.Unmarshal([]byte(cases), &list); err != nil {
		t.Fatal(err)
	}
	for i, c := range list {
		cfg := contracts.DefaultConfig()
		if err := json.Unmarshal(c.Config, &cfg); err != nil {
			t.Fatalf("%s case %d: config %s: %v", label, i, c.Config, err)
		}
		data := secHex(t, c.Data)
		var o contracts.Observation
		if c.Kind == "stream" {
			in, err := New(cfg, c.Hint)
			if err != nil {
				t.Fatalf("%s case %d: %v", label, i, err)
			}
			in.Feed(data)
			if c.Ended {
				in.End("EOF before identification completed")
			}
			if in.NotPorted != nil {
				t.Fatalf("%s case %d: not ported: %v", label, i, in.NotPorted)
			}
			o = in.Observation
		} else {
			d, err := NewDatagram(cfg)
			if err != nil {
				t.Fatal(err)
			}
			if o, err = d.Inspect(data, c.Hint); err != nil {
				t.Fatalf("%s case %d: %v", label, i, err)
			}
		}
		var rows [][]string
		for _, e := range o.Evidence {
			rows = append(rows, []string{e.Field, e.Value, e.Source, e.Strength})
		}
		w := c.Obs
		got := fmt.Sprintf("%s %s %s %s %s %s %s %v", o.Status, o.Transport, optional(o.Encryption), optional(o.ApplicationProtocol),
			optional(o.Application), optional(o.Hostname), o.Scope, rows)
		want := fmt.Sprintf("%s %s %s %s %s %s %s %v", w.Status, w.Transport, optional(w.Encryption), optional(w.ApplicationProtocol),
			optional(w.Application), optional(w.Hostname), w.Scope, w.Evidence)
		if len(w.Evidence) == 0 {
			want = strings.TrimSuffix(want, "[]") + "[]"
		}
		if got != want {
			t.Fatalf("%s case %d (%s %s hint %q):\n got  %s\n want %s", label, i, c.Kind, c.Data, c.Hint, got, want)
		}
		text := fmt.Sprintf("%+v %v", o, rows)
		for _, leak := range leaks {
			if strings.Contains(text, leak) {
				t.Fatalf("%s case %d: %q in the observation: %s", label, i, leak, text)
			}
		}
	}
	return len(list)
}

// mutateBounded flips one byte of each base input count times (seeded) and requires a documented status, no
// leak string and no byte inspected beyond the input.
func mutateBounded(t *testing.T, seed int64, count int, bases [][]byte, datagrams bool, leaks ...string) {
	t.Helper()
	rng := rand.New(rand.NewSource(seed))
	allowed := map[contracts.Status]bool{contracts.Identified: true, contracts.Unknown: true, contracts.Malformed: true, contracts.Detecting: true,
		contracts.BudgetExhausted: true, contracts.Incomplete: true}
	for _, base := range bases {
		for i := 0; i < count; i++ {
			data := append([]byte{}, base...)
			data[rng.Intn(len(data))] = byte(rng.Intn(256))
			var o contracts.Observation
			if datagrams {
				o = datagramObservation(t, contracts.DefaultConfig(), data, "")
			} else {
				cfg := contracts.DefaultConfig()
				cfg.MaxBytes = 4096
				in, _ := New(cfg, "")
				in.Feed(data)
				if in.Metrics.BytesInspected > len(data) {
					t.Fatalf("%x: %d bytes inspected", data, in.Metrics.BytesInspected)
				}
				o = in.Observation
			}
			text := fmt.Sprintf("%+v", o)
			if !allowed[o.Status] {
				t.Fatalf("%x: status %s", data, o.Status)
			}
			for _, leak := range leaks {
				if strings.Contains(text, leak) {
					t.Fatalf("%x: %q leaked: %s", data, leak, text)
				}
			}
		}
	}
}

