// SR-54: authentication mechanism evidence is limited to closed labels; every input of the test_v056 suite (SPNEGO,
// GSS, NTLMSSP and Kerberos tokens, SMB2/SMB1 session setup after NEGOTIATE and its header flags, LDAP bind, HTTP/1
// and HTTP/2 challenges and credentials) gets the reference's answer, and no name, domain, credential or token
// byte appears in an observation or verdict.
func TestSecuritySR54AuthenticationMechanismsAreClosedLabels(t *testing.T) {
	leaks := []string{"alice", "WORKGROUP", "NTLMSSP\x00", "YWxpY2U6czNjcmV0", "TlRMTVNTUAAB", "YIIB", "EXAMPLE.ORG", "creds", "realm=", "s3cret"}
	if n := checkRecorded(t, "SR-54", sr54Cases, leaks...); n < 150 {
		t.Fatalf("only %d recorded cases", n)
	}
	if n := checkVerdicts(t, "SR-54", sr54Verdicts, leaks...); n < 20 {
		t.Fatalf("only %d recorded verdicts", n)
	}
}

// SR-58: RDP security posture comes only from a validated X.224 Connection Request or Confirm; closed labels per
// offered protocol bit, credential mode, selection, server flag and failure code; cookie, routing token and
// correlation id are never emitted; the NLA risk follows the server selection only.
func TestSecuritySR58RDPPostureIsClosedAndFollowsTheSelection(t *testing.T) {
	leaks := []string{"placeholder", "mstshash", "msts="}
	if n := checkRecorded(t, "SR-58", sr58Cases, leaks...); n < 25 {
		t.Fatalf("only %d recorded cases", n)
	}
	if n := checkVerdicts(t, "SR-58", sr58Verdicts, leaks...); n < 8 {
		t.Fatalf("only %d recorded verdicts", n)
	}
	var list []recordedCase
	_ = json.Unmarshal([]byte(sr58Cases), &list)
	labels := map[string]bool{}
	for _, c := range list {
		for _, e := range c.Obs.Evidence {
			if strings.HasPrefix(e[0], "rdp_") {
				labels[e[0]+"="+e[1]] = true
			}
		}
	}
	rng := rand.New(rand.NewSource(60))
	for _, c := range list[:3] {
		base := secHex(t, c.Data)
		for i := 0; i < 300; i++ {
			data := append([]byte{}, base...)
			data[rng.Intn(len(data))] = byte(rng.Intn(256))
			o, _ := streamObservation(t, contracts.DefaultConfig(), data)
			for _, e := range o.Evidence {
				if strings.HasPrefix(e.Field, "rdp_") && (o.Status != contracts.Identified || strings.ContainsAny(e.Value, "=\r\n")) {
					t.Fatalf("mutation %x: %+v in a %s observation", data, e, o.Status)
				}
			}
		}
	}
	if len(labels) == 0 {
		t.Fatal("no RDP posture label recorded")
	}
}

// SR-60: the SNMPv3 security level comes only from msgFlags of a validated message and the discovery marker only from
// the absence of authentication and of an engine ID; no engine ID, user or parameter byte is emitted; discovery
// requests and Reports never raise the SNMPv3 risks.
func TestSecuritySR60SNMPv3LevelsAndDiscovery(t *testing.T) {
	leaks := []string{"operator", "80001f88"}
	if n := checkRecorded(t, "SR-60", sr60Cases, leaks...); n < 6 {
		t.Fatalf("only %d recorded cases", n)
	}
	if n := checkVerdicts(t, "SR-60", sr60Verdicts, leaks...); n < 5 {
		t.Fatalf("only %d recorded verdicts", n)
	}
	var list []recordedCase
	_ = json.Unmarshal([]byte(sr60Cases), &list)
	allowed := map[string]map[string]bool{"snmp_security_level": {"no-auth-no-priv": true, "auth-no-priv": true, "auth-priv": true},
		"snmp_usm_discovery": {"request": true}}
	rng := rand.New(rand.NewSource(62))
	for _, c := range list {
		base := secHex(t, c.Data)
		for i := 0; i < 300; i++ {
			data := append([]byte{}, base...)
			data[rng.Intn(len(data))] = byte(rng.Intn(256))
			o := datagramObservation(t, contracts.DefaultConfig(), data, c.Hint)
			for _, e := range o.Evidence {
				if values, ok := allowed[e.Field]; ok && (!values[e.Value] || o.ApplicationProtocol == nil || *o.ApplicationProtocol != "snmp/3") {
					t.Fatalf("mutation %x: %+v", data, e)
				}
			}
		}
	}
}

// SR-63 (server-name catalog): the built-in catalog maps a normalized server name by label-boundary suffix, longest
// suffix first; configured rules, signatures and structural refinements take precedence; an outer ECH name is never
// mapped; reasons state the name is client-asserted and never carry it; observations are unchanged.
func TestSecuritySR63ServerNameCatalogVerdicts(t *testing.T) {
	if n := checkRecorded(t, "SR-63", sr63aCases); n < 5 {
		t.Fatalf("only %d recorded cases", n)
	}
	if n := checkVerdicts(t, "SR-63", sr63aVerdicts); n < 8 {
		t.Fatalf("only %d recorded verdicts", n)
	}
	var list []recordedVerdict
	_ = json.Unmarshal([]byte(sr63aVerdicts), &list)
	for i, v := range list {
		for _, r := range v.Reasons {
			for _, o := range []*contracts.Observation{v.Client, v.Server} {
				if o != nil && o.Hostname != nil && *o.Hostname != "" && strings.Contains(r, *o.Hostname) {
					t.Fatalf("verdict %d: reason %q carries the hostname", i, r)
				}
			}
		}
	}
}

// SR-50: XMPP stream headers and syslog TCP frames are read within their caps; only closed labels and the to/from
// domain are emitted, never stream ids, JIDs, languages or log content; HTTP-carried applications are named only
// from the structural method or an asserted content class; seeded mutations stay bounded and leak nothing.
func TestSecuritySR50XMPPSyslogAndContentClasses(t *testing.T) {
	leaks := []string{"c2s-0001", "user@", "synthetic", "AAABAAAB", "a>b"}
	if n := checkRecorded(t, "SR-50", sr50Cases, leaks...); n < 200 {
		t.Fatalf("only %d recorded cases", n)
	}
	if n := checkVerdicts(t, "SR-50", sr50Verdicts, leaks...); n < 15 {
		t.Fatalf("only %d recorded verdicts", n)
	}
}
